definition.script:
pipeline {
    agent any

    stages {
        stage('Test Vault Integration') {
            steps {
                withVault(
                    configuration: [
                        vaultUrl: 'https://192.168.249.130:8200',
                        vaultCredentialId: 'vault-jenkins-approle'
                    ],
                    vaultSecrets: [
                        [
                            path: 'secret/jenkins',
                            engineVersion: 2,
                            secretValues: [
                                [
                                    envVar: 'VAULT_USERNAME',
                                    vaultKey: 'username'
                                ]
                            ]
                        ]
                    ]
                ) {
                    sh '''
                        if [ -n "$VAULT_USERNAME" ]; then
                            echo "SUCCESS: Jenkins retrieved the secret from Vault"
                        else
                            echo "FAILURE: Secret was empty"
                            exit 1
                        fi
                    '''
                }
            }
        }
    }
}
